scriptUtil.example:
// 调用模板下服务
var objName = 'namespace.templateName';
// 调用实体模板下对象实例中的服务
var objName = 'namespace.templateName/instanceName';
scriptUtil.executeScriptService({
  objName, // 模板 或者 实例
  serviceName: 'namespace.querySQLExec', // 服务的命名空间+服务别名
  params: {
    // 开发者需要关注后台服务的参数
  },
  version: 'V2',
  cb: function (res) {
    console.log('res', res);
  }
});

// 网页地址为 https://www.baidu.com?id=123&code=456
var data = scriptUtil.getRequestUrl();
console.log(data);
// { id: 123, code: 456 }

// 东八区为 -8
var Offset = scriptUtil.getTimeZone();
console.log(Offset);

var url = '/api/openapi/notification/v1/message';
var param = {
  method: 'POST', // 请求类型，可选 GET、POST、PUT、DELETE
  body: {}, // 非必填
  headers: {} // 非必填
};
scriptUtil.request(url, param).then((res) => {
  console.log(res);
});

scriptUtil.Alert('弹出成功', () => {
  console.log('点击确定');
});

const reg = scriptUtil.regRexGroup('mobilePhone');
reg.test('18866668888'); // true
reg.test('1886666777'); // false

const data = [{ name: '张三', age: 123 }, { name: '李四', age: 33 }];
const map = { name: '姓名', age: '年龄' };
const result = scriptUtil.parseTableMap(data, map, '序号');
// [{ "序号": 1, "姓名": "张三", "年龄": 123 }, ...]

const data = { name: '张三', age: 123, sex: '男' };
const sort = ['sex', 'age', 'name'];
const result = scriptUtil.objKeySort(data, sort);

scriptUtil.JSONToExcelConvertor({
  data: [{ name: '小王', age: '12', sex: '女' }],
  dataTitle: ['姓名', '年纪', '性别'],
  dataKey: ['name', 'age', 'sex'],
  fileName: '测试文件',
  extension: 'xls'
});

// 空页面
scriptUtil.openPage('url', '_blank');

// 替换当前页面
scriptUtil.openPage('url', '_self');

// 宽高配置的空页面
scriptUtil.openPage('url', '_blank', true, '{"height":400,"width":400}');

const param = {
  'namespace.p1': 'p1',
  'namespace.p2': 'p2'
};
scriptUtil.addDataTable(
  {
    dataSource: 'namespace.tableName',
    properties: [param], // 一定要是 Array 格式
    version: 'V2'
  },
  function (res) {
    console.log('res', res);
  }
);

const param = {
  id: 'xxx' // 只能根据 id 删除
};
scriptUtil.delDataTable(
  {
    dataSource: 'namespace.tableName',
    properties: [param], // 一定要是 Array 格式
    version: 'V2'
  },
  function (res) {
    console.log('res', res);
  }
);

// 修改条件：code 字段为 1623219467408
// 修改结果：comDetailAdd（公司详细地址）为浙江省宁波市
var dataSource = 'supyoung_companyreg.company_reg';
var param = {
  comDetailAdd: '浙江省宁波市' // 需要修改的字段
};
var keys = {
  'supyoung_companyreg.code': '1623219467408' // key 必须带命名空间
};
scriptUtil.updateDataTable(
  {
    dataSource,
    properties: [param], // 一定要是 Array 格式
    keys,
    version: 'V2'
  },
  function (res) {
    console.log('res', res);
  }
);

var namespace = 'supyoung_companyreg';
var dataSource = namespace + '.company_reg';
scriptUtil.queryDataTable(
  {
    dataSource,
    filters: {
      fields: ['desc'], // 查询指定字段
      order: [
        {
          order: 'code', // 排序的字段
          sort: 'desc' // desc 降序  asc 升序
        }
      ],
      distinct: true,
      pageIndex: 1,
      pageSize: 5,
      'supyoung_companyreg.company': '%xx%' // 查询公司名为 xx 的数据（一定要加上命名空间）
    },
    version: 'V2'
  },
  function (res) {
    console.log('res', res);
  }
);

// 执行 sql 方法
scriptUtil.callSqlFunction({
  name: 'sqlName',
  params: {
    page: 1, // 分页参数：页码
    per_page: 5 // 分页参数：每页数量
    // 等其他 sql 需要的入参
  },
  enableTotal: false // true 支持查询分页
}).then(function (res) {
  console.log('then:res');
});

scriptUtil.getUserInfo(function (res) {
  // res 为当前用户的信息
  console.log('res', res);
});

$os.example:
// additionalData { code: 123, name: '张三' }，和页面表单组件值一起，存入到表单模板里面
$os.dataSave(template, additionalData).then((res) => {
  console.log(res);
});

// 删除表单模板中 age 为 12、code 为 456 的数据
$os.dataDelete(template).where('age = 12 and code = 456').then((res) => {
  console.log(res);
});

$os.dataDelete(template).where({ age: 12, code: 456 }).then((res) => {
  console.log(res);
});

// 将 age 为 12、code 为 456 的数据的 name 字段值改成张三
$os.dataUpdate(template)
  .data({ name: '张三' })
  .where('age = 12 and code = 456')
  .then((res) => {
    console.log(res);
  });

$os.dataUpdate(template)
  .data({ name: '张三' })
  .where({ age: 12, code: 456 })
  .then((res) => {
    console.log(res);
  });

// 调用表单模板下的服务
$os.execService('nameSpace.template', 'serviceName', params).then((res) => {
  console.log(res);
});

// 调用物模板实例下的服务
$os.execService('nameSpace.template.instance', 'serviceName', params).then((res) => {
  console.log(res);
});
